INSERT INTO public.quiz_questions (id, quiz_id, question, kind, options, correct_index, explanation, position)
SELECT v.id, v.quiz_id, v.question, v.kind, v.options, v.correct_index, v.explanation, v.position
  FROM (VALUES
    ('b19312cf-f9aa-5485-92b5-3911ae4eb443'::uuid, '054fc2a3-88ec-5292-b09d-f5cb1ed94e8d'::uuid, 'Quel est le signe du produit (−7) × (+3) ?', 'mcq', '["Négatif","Positif","Nul","Cela dépend de l’ordre"]'::jsonb, 0, 'Deux signes contraires donnent un résultat négatif.', 1),
    ('692df57f-8fc7-56f8-86ba-f56512089249'::uuid, '054fc2a3-88ec-5292-b09d-f5cb1ed94e8d'::uuid, 'Combien vaut (−36) ÷ (−4) ?', 'mcq', '["+9","−9","+40","−40"]'::jsonb, 0, 'Deux signes identiques donnent un quotient positif.', 2),
    ('9c99ce9d-7e7d-512e-99cf-b1a82fc3e180'::uuid, '054fc2a3-88ec-5292-b09d-f5cb1ed94e8d'::uuid, 'Quel est le signe de (−2) × (−3) × (−5) ?', 'mcq', '["Négatif","Positif","Nul","Indéterminé"]'::jsonb, 0, 'Trois facteurs négatifs : un nombre impair donne un produit négatif.', 3),
    ('6b223143-c094-57ff-a1c6-5b32c8e7d331'::uuid, '054fc2a3-88ec-5292-b09d-f5cb1ed94e8d'::uuid, 'Combien vaut (−3)² ?', 'mcq', '["+9","−9","−6","+6"]'::jsonb, 0, 'Le carré porte sur le nombre entier, signe compris.', 4),
    ('1cefd463-4d5f-55d8-ae85-22481b2969ef'::uuid, '054fc2a3-88ec-5292-b09d-f5cb1ed94e8d'::uuid, 'Combien vaut −3² ?', 'mcq', '["−9","+9","−6","+6"]'::jsonb, 0, 'Sans parenthèses, le carré ne porte que sur le 3.', 5),
    ('5503f2f8-45e9-569e-a54c-c52ae0bc736e'::uuid, '054fc2a3-88ec-5292-b09d-f5cb1ed94e8d'::uuid, 'Quel est l’opposé de −5 ?', 'mcq', '["+5","−1/5","+1/5","−5"]'::jsonb, 0, 'L’inverse serait −1/5 : les deux notions ne se confondent pas.', 6),
    ('9f510c65-1b03-56c2-bd2d-06457c900fc6'::uuid, '054fc2a3-88ec-5292-b09d-f5cb1ed94e8d'::uuid, 'Quand un produit de facteurs est-il nul ?', 'mcq', '["Quand au moins l’un des facteurs est nul","Quand tous les facteurs sont négatifs","Quand il y a un nombre pair de facteurs","Jamais"]'::jsonb, 0, 'C’est la propriété qui sert à résoudre les équations produit.', 7),
    ('8c557382-f7a3-590b-9dd0-e304c847f251'::uuid, '054fc2a3-88ec-5292-b09d-f5cb1ed94e8d'::uuid, 'La règle des signes de la division diffère de celle de la multiplication.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle est identique, mot pour mot.', 8),
    ('1dccd485-552e-5e10-bb38-c597ba930155'::uuid, '3e500411-7a59-5e40-9896-9a8f8449dfcc'::uuid, 'Quel nombre est le plus grand : −3 ou −7 ?', 'mcq', '["−3","−7","Ils sont égaux","On ne peut pas comparer"]'::jsonb, 0, 'Entre deux négatifs, le plus grand est celui dont la distance à zéro est la plus petite.', 1),
    ('9a85563d-3133-5c41-8753-2cdf77785134'::uuid, '3e500411-7a59-5e40-9896-9a8f8449dfcc'::uuid, 'Comment compare-t-on deux fractions de dénominateurs différents ?', 'mcq', '["On les réduit au même dénominateur","On compare les numérateurs directement","On additionne numérateur et dénominateur","On les convertit en pourcentages obligatoirement"]'::jsonb, 0, 'C’est la seule méthode sûre.', 2),
    ('644e041e-b6aa-5705-8796-32966fe0426e'::uuid, '3e500411-7a59-5e40-9896-9a8f8449dfcc'::uuid, 'Entre 3/10 et 3/4, laquelle est la plus grande ?', 'mcq', '["3/4","3/10","Elles sont égales","On ne peut pas savoir"]'::jsonb, 0, 'À numérateur égal, plus le dénominateur est grand, plus la fraction est petite.', 3),
    ('512dc241-d72a-52cb-a835-9dfc97fa2632'::uuid, '3e500411-7a59-5e40-9896-9a8f8449dfcc'::uuid, 'Que signifie encadrer un nombre ?', 'mcq', '["Le placer entre deux bornes","L’arrondir à l’unité","Le multiplier par 10","Le convertir en fraction"]'::jsonb, 0, 'On écrit a < x < b.', 4),
    ('e24ea542-01aa-5d22-a628-57743f3b63cc'::uuid, '3e500411-7a59-5e40-9896-9a8f8449dfcc'::uuid, 'Qu’est-ce que l’amplitude d’un encadrement ?', 'mcq', '["L’écart entre les deux bornes","La valeur du nombre encadré","Le nombre de décimales","La somme des deux bornes"]'::jsonb, 0, 'Plus elle est petite, plus l’encadrement est précis.', 5),
    ('6260ad65-5b59-53d5-a4d1-9d27224d9c31'::uuid, '3e500411-7a59-5e40-9896-9a8f8449dfcc'::uuid, 'Quel est l’encadrement de √2 au dixième ?', 'mcq', '["1,4 < √2 < 1,5","1 < √2 < 2","1,41 < √2 < 1,42","1,3 < √2 < 1,4"]'::jsonb, 0, '√2 vaut environ 1,4142.', 6),
