    ('755909b8-f941-50c5-b39d-0d91e32c9eba'::uuid, '3e500411-7a59-5e40-9896-9a8f8449dfcc'::uuid, 'Un nombre positif peut être inférieur à un nombre négatif.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Tout positif est supérieur à tout négatif.', 8),
    ('d2438289-9f6e-5509-8a67-be4817c8de91'::uuid, '6ebc8210-1e5d-5ea8-a399-c81227568cae'::uuid, 'Que peut-on faire sans changer la valeur d’une fraction ?', 'mcq', '["Multiplier ou diviser numérateur et dénominateur par un même nombre non nul","Ajouter le même nombre en haut et en bas","Soustraire le même nombre en haut et en bas","Échanger numérateur et dénominateur"]'::jsonb, 0, 'C’est la propriété fondamentale des fractions.', 1),
    ('bf8655be-61a3-5141-b8f3-af56a8545d27'::uuid, '6ebc8210-1e5d-5ea8-a399-c81227568cae'::uuid, 'Quelle est la forme simplifiée de 24/36 ?', 'mcq', '["2/3","12/18","4/6","3/4"]'::jsonb, 0, 'On divise les deux termes par 12.', 2),
