    ('6fef8ed3-2d31-5cee-9029-31cbf3da8cd6'::uuid, '6ebc8210-1e5d-5ea8-a399-c81227568cae'::uuid, 'Les fractions 6/9 et 8/12 sont-elles égales ?', 'mcq', '["Oui, car 6 × 12 = 9 × 8","Non, car les numérateurs diffèrent","Non, car les dénominateurs diffèrent","On ne peut pas le savoir"]'::jsonb, 0, 'Les deux produits en croix valent 72.', 5),
    ('e0fa7c7b-3e26-5e90-a26f-31a04f2317fc'::uuid, '6ebc8210-1e5d-5ea8-a399-c81227568cae'::uuid, 'Que vaut 0/a, pour a non nul ?', 'mcq', '["0","1","a","Cela n’existe pas"]'::jsonb, 0, 'En revanche a/0 n’a pas de sens.', 6),
    ('ed63a5fb-40ec-5fca-96e1-aed2db955e3b'::uuid, '6ebc8210-1e5d-5ea8-a399-c81227568cae'::uuid, 'Quel dénominateur commun choisir pour 2/3 et 3/4 ?', 'mcq', '["12","7","6","5"]'::jsonb, 0, 'C’est le plus petit multiple commun de 3 et 4.', 7),
    ('6b1d1ef0-43cd-5f7b-89fc-646d68a70435'::uuid, '6ebc8210-1e5d-5ea8-a399-c81227568cae'::uuid, 'On peut simplifier une fraction en retirant le même terme au numérateur et au dénominateur.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'On ne simplifie que par multiplication ou division.', 8),
