    ('119198d1-bf2d-5d72-957d-15bbc73cab49'::uuid, 'fa11d0bb-a41a-52a2-947d-6bd62be296b5'::uuid, 'Pour additionner deux fractions, on additionne aussi les dénominateurs.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Le dénominateur commun reste inchangé.', 8),
