    ('294cc8ad-42ad-5805-b826-888b55f52e28'::uuid, '2607f59b-40b8-524c-bdd3-a3b7099ae319'::uuid, 'La décomposition en facteurs premiers d’un entier peut s’écrire de plusieurs façons.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle est unique, à l’ordre des facteurs près.', 8),
