    ('0fd40994-7d97-5dec-933e-c90f13c7fe79'::uuid, '37a1a339-c78b-563d-86c9-5ca1a4b6f9a8'::uuid, 'Quelle est la solution de 5x − 3 = 2x + 9 ?', 'mcq', '["x = 4","x = 2","x = 12","x = 6"]'::jsonb, 0, '3x = 12 après regroupement.', 3),
