    ('9ceba09d-ca5d-592c-bb4e-732ac45cacb7'::uuid, '57978780-e661-5d0f-a616-ff06d05daf17'::uuid, 'Que faut-il vérifier avant de conclure ?', 'mcq', '["La vraisemblance du résultat dans le contexte","La longueur de la rédaction","Le nombre d’étapes","La présence d’un schéma"]'::jsonb, 0, 'Un âge négatif ou un nombre de personnes décimal signale une erreur.', 7),
    ('6da0b097-0635-57d0-98b1-837094b29d6e'::uuid, '57978780-e661-5d0f-a616-ff06d05daf17'::uuid, 'Modéliser consiste d’abord à trouver le résultat.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il s’agit d’abord d’écrire correctement le problème ; le calcul vient ensuite.', 8),
    ('139d012e-46ca-58a2-8b5a-c9d9ba9362e5'::uuid, '766ce027-ba58-5e42-851f-8827d33560ed'::uuid, 'Qu’est-ce que l’effectif d’une valeur ?', 'mcq', '["Le nombre d’individus qui portent cette valeur","La somme de toutes les valeurs","La valeur la plus fréquente","L’écart entre deux valeurs"]'::jsonb, 0, 'L’effectif total est la somme de tous les effectifs.', 1),
    ('77168a2f-4d24-5f03-9b85-d4f87b7ff0f1'::uuid, '766ce027-ba58-5e42-851f-8827d33560ed'::uuid, 'Comment calcule-t-on une fréquence ?', 'mcq', '["Effectif de la valeur ÷ effectif total","Effectif total ÷ effectif de la valeur","Valeur × effectif","Somme des valeurs ÷ 100"]'::jsonb, 0, 'La somme des fréquences vaut 1, soit 100 %.', 2),
    ('4683dab8-71cb-5212-afb6-ba188ffa148b'::uuid, '766ce027-ba58-5e42-851f-8827d33560ed'::uuid, 'Qu’est-ce que l’étendue d’une série ?', 'mcq', '["La différence entre la plus grande et la plus petite valeur","La valeur du milieu","La moyenne des valeurs","Le nombre de valeurs"]'::jsonb, 0, 'Elle mesure la dispersion.', 3),
