    ('11767673-ab3b-51b3-a744-606d5e5295ca'::uuid, 'e5cdaa19-81b3-55a9-bace-c381bc536cca'::uuid, 'Entre quelles valeurs une probabilité est-elle comprise ?', 'mcq', '["Entre 0 et 1","Entre −1 et 1","Entre 0 et 100","Entre 1 et 6"]'::jsonb, 0, '0 = impossible, 1 = certain.', 1),
    ('0d51c5bc-d901-5863-a142-480841fe9fb6'::uuid, 'e5cdaa19-81b3-55a9-bace-c381bc536cca'::uuid, 'Comment calcule-t-on une probabilité en situation d’équiprobabilité ?', 'mcq', '["Issues favorables ÷ issues possibles","Issues possibles ÷ issues favorables","Issues favorables × nombre d’essais","Nombre d’essais ÷ 100"]'::jsonb, 0, 'Toutes les issues doivent avoir la même chance.', 2),
    ('645cccb8-1083-575a-af5a-0e777e7e0810'::uuid, 'e5cdaa19-81b3-55a9-bace-c381bc536cca'::uuid, 'Dans une urne de 5 boules rouges et 3 bleues, quelle est la probabilité de tirer une rouge ?', 'mcq', '["5/8","5/3","3/8","1/2"]'::jsonb, 0, 'Cinq issues favorables sur huit possibles.', 3),
    ('a6f9fc4a-badf-591c-80c4-cd01f00f7591'::uuid, 'e5cdaa19-81b3-55a9-bace-c381bc536cca'::uuid, 'Comment calcule-t-on la probabilité de l’événement contraire ?', 'mcq', '["1 − P(A)","P(A) − 1","1 ÷ P(A)","100 − P(A)"]'::jsonb, 0, 'Utile pour les événements « au moins un ».', 4),
    ('e700823b-62c1-51fd-844f-44d019fa83bb'::uuid, 'e5cdaa19-81b3-55a9-bace-c381bc536cca'::uuid, 'Que fait-on le long d’une branche d’arbre de probabilités ?', 'mcq', '["On multiplie les probabilités","On les additionne","On les soustrait","On prend la plus grande"]'::jsonb, 0, 'On additionne ensuite les branches favorables.', 5),
