    ('4613bead-be5e-5db8-806d-95ca66491035'::uuid, 'cafa0221-771e-5d4e-bbb0-7f906d025246'::uuid, 'Comment reconnaît-on une proportionnalité dans un tableau ?', 'mcq', '["Le quotient entre les deux lignes est constant","La différence entre les deux lignes est constante","La somme des lignes est constante","Les valeurs sont croissantes"]'::jsonb, 0, 'Ce quotient est le coefficient de proportionnalité.', 1),
