    ('9df64f51-df9c-5278-a5b8-ca2dda76b2c6'::uuid, '7c210e54-08fc-5cad-84f2-e18a37b89f85'::uuid, 'Combien font 30 % de 80 € ?', 'mcq', '["24 €","30 €","26,67 €","2,4 €"]'::jsonb, 0, '80 × 0,3.', 2),
