    ('4504970b-3304-5db7-b8c4-7232eb2e99c6'::uuid, 'f0dfcef5-337f-506c-9897-7fc65938e5a8'::uuid, 'Quelle grandeur est un quotient ?', 'mcq', '["La vitesse","L’aire","Le volume","L’énergie en kilowattheures"]'::jsonb, 0, 'Distance divisée par durée.', 2),
