    ('f8f881a8-f3bc-530e-8e77-114da70f185d'::uuid, 'f0dfcef5-337f-506c-9897-7fc65938e5a8'::uuid, 'Quelle est l’unité de la masse volumique ?', 'mcq', '["g/cm³","cm³/g","g × cm³","g/cm"]'::jsonb, 0, 'Masse divisée par volume.', 4),
    ('2a919e98-dfff-59bd-955c-d9a26753abab'::uuid, 'f0dfcef5-337f-506c-9897-7fc65938e5a8'::uuid, 'Le kilowattheure est-il un produit ou un quotient ?', 'mcq', '["Un produit : puissance × durée","Un quotient : puissance ÷ durée","Une grandeur simple","Un quotient : durée ÷ puissance"]'::jsonb, 0, '1 kW pendant 1 h.', 5),
    ('3c1abd76-e0b8-5e43-8726-2fc39703b112'::uuid, 'f0dfcef5-337f-506c-9897-7fc65938e5a8'::uuid, 'Quelle grandeur mesure une densité de population ?', 'mcq', '["Le nombre d’habitants par km²","La superficie par habitant","Le nombre d’habitants multiplié par la superficie","Le nombre de logements"]'::jsonb, 0, 'C’est un quotient : hab/km².', 6),
