    ('26a5b8b0-22bd-55a5-a177-27f8901a7146'::uuid, 'f0dfcef5-337f-506c-9897-7fc65938e5a8'::uuid, 'On peut calculer une vitesse en km/h à partir d’une durée en minutes sans conversion.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Les unités doivent être cohérentes avant tout calcul.', 8),
    ('7cf2febb-ab05-5323-a465-3b8b41705052'::uuid, '221e41e7-ddc6-5108-be4c-d892d8199532'::uuid, 'Quelle est la formule de la vitesse moyenne ?', 'mcq', '["v = d ÷ t","v = d × t","v = t ÷ d","v = d + t"]'::jsonb, 0, 'On en déduit d = v × t et t = d ÷ v.', 1),
