    ('d6b17662-e32a-57e3-9c2a-d788e35dc262'::uuid, '221e41e7-ddc6-5108-be4c-d892d8199532'::uuid, 'Comment s’écrit 1 h 30 min en heures décimales ?', 'mcq', '["1,5 h","1,30 h","1,3 h","90 h"]'::jsonb, 0, 'C’est l’erreur la plus fréquente du chapitre.', 3),
