    ('8fa6836a-e531-5393-8a64-039de8aed77c'::uuid, '3821ca95-a7d8-5180-bdd4-378531949ea8'::uuid, 'À combien de kg/m³ correspond 1 g/cm³ ?', 'mcq', '["1 000 kg/m³","1 kg/m³","100 kg/m³","10 000 kg/m³"]'::jsonb, 0, 'On convertit numérateur et dénominateur séparément.', 7),
