    ('bed457b2-0f5c-5912-a1a0-0c86744d2161'::uuid, 'bc1b9625-7a79-5577-b6e1-e7eec9fe7d61'::uuid, 'Combien vaut la somme des angles d’un triangle ?', 'mcq', '["180°","360°","90°","Cela dépend du triangle"]'::jsonb, 0, 'C’est vrai pour tout triangle.', 1),
    ('0af857a6-82d5-544d-8505-6868e5a76f20'::uuid, 'bc1b9625-7a79-5577-b6e1-e7eec9fe7d61'::uuid, 'Que peut-on dire des angles d’un triangle équilatéral ?', 'mcq', '["Ils mesurent tous 60°","Ils mesurent tous 45°","Deux d’entre eux sont égaux","L’un d’eux est droit"]'::jsonb, 0, '180° ÷ 3.', 2),
    ('fdd9bee6-b27b-5b3b-858d-2b97aa021ea5'::uuid, 'bc1b9625-7a79-5577-b6e1-e7eec9fe7d61'::uuid, 'Que dit l’inégalité triangulaire ?', 'mcq', '["La plus grande longueur doit être inférieure à la somme des deux autres","Les trois côtés doivent être différents","Le plus grand angle est opposé au plus petit côté","La somme des côtés vaut 180"]'::jsonb, 0, '3, 4 et 9 ne forment pas un triangle.', 3),
    ('ab2faf7c-39bd-57bd-9397-5b067dd61841'::uuid, 'bc1b9625-7a79-5577-b6e1-e7eec9fe7d61'::uuid, 'Que se passe-t-il si la plus grande longueur égale la somme des deux autres ?', 'mcq', '["Les trois points sont alignés","Le triangle est équilatéral","Le triangle est rectangle","Le triangle est isocèle"]'::jsonb, 0, 'Le triangle est alors « aplati ».', 4),
